import { freezeDesign } from './catalogs.mjs';
import { CONTENT_ARTWORK_LOAD_TIMEOUT_MS, CONTENT_ASSET_MAX_BYTES } from './limits.mjs';

const verified = new WeakMap();
function imageDataURL(bytes, mime, signal) {
  if (typeof FileReader === 'function')
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      let settled = false;
      const finish = (error) => {
        if (settled) return;
        settled = true;
        signal.removeEventListener('abort', cancel);
        reader.onload = reader.onerror = reader.onabort = null;
        if (error) reject(error);
        else resolve(reader.result);
      };
      const cancel = () => {
        finish(new DOMException('Artwork preview cancelled.', 'AbortError'));
        reader.abort();
      };
      reader.onload = () => finish();
      reader.onerror = () => finish(reader.error ?? new Error('Artwork encoding failed.'));
      reader.onabort = cancel;
      signal.addEventListener('abort', cancel, { once: true });
      if (signal.aborted) return cancel();
      try {
        reader.readAsDataURL(new Blob([bytes], { type: mime }));
      } catch (error) {
        finish(error);
      }
    });
  let binary = '';
  for (let start = 0; start < bytes.length; start += 16384)
    binary += String.fromCharCode(...bytes.subarray(start, start + 16384));
  return Promise.resolve(`data:${mime};base64,${btoa(binary)}`);
}

async function transact(mode, body, signal) {
  abort(signal);
  const db = await open(signal);
  abort(signal);
  required(!closed, 'Managed media store is closed.');
  return new Promise((resolve, reject) => {
    const tx = createTransaction(db, storesInUse, mode),
      stores = Object.fromEntries(storesInUse.map((name) => [name, tx.objectStore(name)]));
    let result,
      failure = null,
      settled = false;
    const finish = (error) => {
      if (settled) return;
      settled = true;
      signal?.removeEventListener('abort', cancel);
      if (error) reject(error);
      else resolve(result);
    };
    const fail = (error) => {
      failure = error;
      try {
        tx.abort();
      } catch {
        finish(error);
      }
    };
    const cancel = () => {
      const previous = failure;
      failure = new DOMException('Media operation cancelled.', 'AbortError');
      try {
        tx.abort();
      } catch (e) {
        if (e?.name === 'InvalidStateError') failure = previous;
        else finish(e);
      }
    };
    tx.oncomplete = () => finish(failure);
    tx.onerror = () => {
      failure ??= tx.error;
    };
    tx.onabort = () => finish(failure || tx.error || new Error('Media transaction failed.'));

// Player panels such as Music Library create their own dialog after boot.
// Observe dialog attachment/replacement only; never decorate general content,
// canvas, HUD, input descendants or separate authoring documents.
const Observer = doc.defaultView?.MutationObserver ?? globalThis.MutationObserver;
if (typeof Observer === 'function') {
  observer = new Observer((records) => {
    if (disposed) return;
    for (const [root, decoration] of decorations) {
      if (root.isConnected) continue;
      decoration.remove();
      decorations.delete(root);
    }
    for (const record of records) {
      if (record.target?.tagName === 'DIALOG') decorate(record.target);
      for (const node of record.addedNodes ?? []) {
        if (node.tagName === 'DIALOG') decorate(node);
        for (const dialog of node.querySelectorAll?.('dialog') ?? []) decorate(dialog);
      }
    }
  });
  observer.observe(body, { childList: true, subtree: true });
}

const records = (changes) => {
  if (destroyed) return;
  for (const change of changes) {
    if (change.type === 'childList') {
      // An already-open dialog can arrive inside an inserted subtree without
      // an observed open attribute change. Removal can also leave one of
      // several pre-existing dialogs as the only unambiguous fallback.
      if (
        emptyKnown &&
        (containsDialog(change.addedNodes) || containsDialog(change.removedNodes))
      )
        emptyKnown = false;
      continue;
    }
    if (!isDialog(change.target) || change.attributeName !== 'open') continue;
    emptyKnown = false;
    // takeRecords preserves mutation order even if several dialogs opened in one task.
    if (change.oldValue === null && isOpen(change.target)) {
      opened(change.target, previousFocus, true);
    }
  }
};
const Observer = doc.defaultView?.MutationObserver ?? globalThis.MutationObserver;
const observer = typeof Observer === 'function' ? new Observer(records) : null;
observer?.observe(doc, {
  subtree: true,
  childList: true,
  attributes: true,
  attributeFilter: ['open'],
  attributeOldValue: true,
});

if (featured && onFeatured)
  featured.onclick = async () => {
    if (featured.disabled || destroyed) return;
    const visit = homeVisit;
    const labelNode = featured.querySelector('[data-field-kit-copy]') ?? featured;
    const label = liveLabel(labelNode);
    pause(true);
    featured.disabled = true;
    localizedText(labelNode, () => copy('title.preparing'));
    try {
      if ((await onFeatured()) && !destroyed && homeVisit === visit && topDialog() === home) {
        openMissions();
      }
    } finally {
      if (!destroyed) {
        featured.disabled = false;
        localizedText(labelNode, label);
      }
    }
  };
if (featured && onTitleStart) featured.onclick = () => launchTitle(featured, onTitleStart);

function queue() {
  if (!regionData.count) {
    stop();
    return;
  }
  if (!disposed && wanted && ready && !lost && frame === null && win?.requestAnimationFrame)
    frame = win.requestAnimationFrame(tick);
}
function tick(stamp) {
  frame = null;
  if (disposed || !wanted || !ready || lost) return;
  if (source() !== current || image.complete === false) {
    prepare();
    return;
  }
  if (lastStamp === null) lastDraw = stamp;
  else {
    const delta = stamp - lastStamp;
    // Suspended browsers never fast-forward the picture when callbacks return.
    if (delta >= 0 && delta <= 250) {
      seconds += delta / 1000;
    }
  }
  lastStamp = stamp;
  if (stamp - lastDraw >= FRAME_MS - 0.01) {
    try {
      draw();
    } catch {
      unavailable(current);
      return;
    }
    lastDraw = stamp;
  }
  queue();
}
